&lt;b&gt;Tr&#233;sor&lt;/b&gt; &#233;quipement de PNJ (&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures#Armuredepeau.html&quot; title=&quot;armure de peau (armure)&quot;&gt;armure de peau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Forme-Animale.html&quot; title=&quot;forme animale (propri&#233;t&#233;)&quot;&gt;forme animale&lt;/a&gt; +2&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-(Arme).html&quot; title=&quot;B&#226;ton&quot;&gt;b&#226;ton&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Gardienne.html&quot; title=&quot;gardienne (propri&#233;t&#233;)&quot;&gt;gardien&lt;/a&gt; +2&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Prouesse-Mentale.html&quot; title=&quot;Bandeau de prouesse mentale&quot;&gt;bandeau de prouesse mentale +2&lt;/a&gt;&lt;/i&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;Sag&quot;&gt;Sag&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt;], &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Protection.html&quot; title=&quot;Anneau de protection&quot;&gt;anneau de protection +2&lt;/a&gt;&lt;/i&gt;)
